#include <complex>
#include <constants_mod.hpp>
#include <epinv_mod.hpp>
#include <epinv2_mod.hpp>
#include <mxpart_mod.hpp>
#include <nflav_mod.hpp>
#include <scale_mod.hpp>
#include <FArray.hpp>
#include <Need.hpp>
#include <SpecialFunctions.hpp>

// forward declarations for the helper functions defined later in this file;
// they are only ever called from within this translation unit.
static std::complex<double> FF(int i, int j, int k, FArray2D<double>& s);
static int krondel(int i, int j);

void fillEij(FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
             FArray2D<double>& s, FArray2D<std::complex<double>>& aQQ_qb0,
             FArray2D<std::complex<double>>& aQQ_QQb0, FArray2D<std::complex<double>>& aq_qb0,
             FArray2D<std::complex<double>>& aq_QQb0, FArray2D<std::complex<double>>& EQQ_qb,
             FArray2D<std::complex<double>>& EQQ_QQb) {
  // --- pentagon and box finite contributions from 9405386, Eqs. (11)-(13)
  using namespace constants_mod;
  using namespace epinv_mod;
  using namespace epinv2_mod;
  using namespace mxpart_mod;
  using namespace nflav_mod;
  using namespace scale_mod;

  int q, QQ, qb, QQb, g;
  int P, Pb;
  // definitions of helicity-dependent momenta , Eq. (5)
  int pntr_r_data[2], pntr_RR_data[2];
  FArray1D<int> pntr_r(pntr_r_data, 2);
  FArray1D<int> pntr_RR(pntr_RR_data, 2);

  int hq, hQQ, r, RR;

  FArray1D<std::complex<double>> HQQ_QQb(2), HQQ_qb(2), Hq_QQb(2);
  FArray1D<std::complex<double>> aQQ_QQb0_plus(2), aQQ_qb0_plus(2), aq_QQb0_plus(2);

  // statement functions
  // Eq. (26)
  auto h = [&](int i, int j, int k, int l) -> std::complex<double> {
    return std::pow(za(i, k) * za(j, l) / (za(i, l) * za(j, k)), 2);
  };
  // Eq. (27)
  auto htil = [&](int i, int j, int k, int l) -> std::complex<double> {
    return std::pow(h(i, j, k, l), (1 - krondel(i, k)) * (1 - krondel(j, l)));
  };
  // Eq. (28)
  auto GGg4 = [&](int r, int a, int AA, int gg, int RR) -> std::complex<double> {
    return std::pow(h(r, a, gg, RR), krondel(RR, AA)) * FF(a, AA, gg, s);
  };
  auto GGg2 = [&](int r, int gg, int a, int AA, int RR) -> std::complex<double> {
    return std::pow(h(r, gg, AA, RR), krondel(r, a)) * FF(gg, a, AA, s);
  };

  // pointers, noting that the notation of the paper is translated as follows:
  //  q -> q, Q -> QQ, qbar -> qb, Qbar -> QQb
  q = 1;
  QQ = 2;
  qb = 3;
  QQb = 4;
  g = 5;
  P = QQ;
  Pb = QQb;
  pntr_r_data[0] = q;
  pntr_r_data[1] = qb;
  pntr_RR_data[0] = QQ;
  pntr_RR_data[1] = QQb;

  for (hq = 1; hq <= 2; ++hq) {
    r = pntr_r(hq);
    for (hQQ = 1; hQQ <= 2; ++hQQ) {
      RR = pntr_RR(hQQ);

      // Eq. (29)
      EQQ_qb(hq, hQQ) =                                                          // @coverage-probe
          -aQQ_qb0(hq, hQQ) *
              (xn * (FF(qb, g, P, s) + h(r, qb, Pb, RR) * FF(qb, q, Pb, s) +
                     h(r, q, g, RR) * FF(q, qb, g, s) + h(r, g, Pb, RR) * FF(g, P, Pb, s) +
                     h(r, q, P, RR) * FF(q, Pb, P, s)) -
               one / xn *
                   (-h(r, q, Pb, RR) * (FF(q, P, Pb, s) + FF(q, qb, Pb, s)) + FF(q, g, Pb, s) -
                    h(r, qb, P, RR) * (FF(qb, Pb, P, s) + FF(qb, q, P, s)) + FF(qb, g, P, s) +
                    h(r, qb, Pb, RR) * (FF(qb, P, Pb, s) + FF(qb, q, Pb, s)) - FF(qb, g, Pb, s) +
                    h(r, q, P, RR) * (FF(q, qb, P, s) + FF(q, Pb, P, s)) - FF(q, g, P, s))) +
          aQQ_QQb0(hq, hQQ) *
              (xn * h(r, g, Pb, RR) * FF(g, P, Pb, s) -
               one / xn *
                   (-FF(qb, g, Pb, s) + h(r, qb, g, RR) * FF(qb, q, g, s) + FF(Pb, g, q, s) -
                    h(r, q, g, RR) * FF(q, qb, g, s) - htil(r, Pb, g, RR) * FF(Pb, P, g, s) -
                    h(r, q, Pb, RR) * (FF(q, P, Pb, s) - FF(q, qb, Pb, s)) +
                    h(r, qb, Pb, RR) * (FF(qb, P, Pb, s) - FF(qb, q, Pb, s)) +
                    GGg4(r, qb, Pb, g, RR) - GGg4(r, qb, P, g, RR) + GGg4(r, q, P, g, RR) -
                    GGg4(r, q, Pb, g, RR))) +
          aq_qb0(hq, hQQ) *
              (xn * h(r, q, g, RR) * FF(q, qb, g, s) -
               one / xn *
                   (FF(Pb, g, q, s) - h(r, g, Pb, RR) * FF(g, P, Pb, s) - FF(P, g, q, s) +
                    h(r, g, P, RR) * FF(g, Pb, P, s) - htil(r, g, q, RR) * FF(g, qb, q, s) -
                    h(r, q, Pb, RR) * (FF(q, qb, Pb, s) - FF(q, P, Pb, s)) +
                    h(r, q, P, RR) * (FF(q, qb, P, s) - FF(q, Pb, P, s)) +
                    GGg2(r, g, qb, Pb, RR) - GGg2(r, g, q, Pb, RR) + GGg2(r, g, q, P, RR) -
                    GGg2(r, g, qb, P, RR)));
    }
  }

  for (hq = 1; hq <= 2; ++hq) {
    // pointers, noting that the notation of the paper is translated as follows:
    //  q -> q, Q -> QQ, qbar -> qb, Qbar -> QQb
    // and that the hq=1 corresponds to qb<->q, Qbar<->Q, c.f. Eqs. (14) and (15)
    if (hq == 2) {
      q = 1;
      QQ = 2;
      qb = 3;
      QQb = 4;
      g = 5;
    } else {
      q = 3;
      QQ = 4;
      qb = 1;
      QQb = 2;
      g = 5;
    }
    P = QQ;
    Pb = QQb;
    pntr_r_data[0] = q;
    pntr_r_data[1] = qb;
    pntr_RR_data[0] = QQ;
    pntr_RR_data[1] = QQb;

    // Eq. (31)
    HQQ_QQb(1) =
        xn * (FF(qb, g, q, s) + FF(P, q, g, s) - FF(Pb, g, qb, s) - FF(P, g, q, s) -
              FF(P, q, qb, s) - FF(g, q, qb, s) + h(qb, g, Pb, P) * FF(g, qb, Pb, s) -
              h(qb, q, Pb, P) * FF(q, qb, Pb, s) - h(qb, g, q, P) * FF(g, qb, q, s)) -
        one / xn *
            (FF(qb, q, P, s) - FF(qb, q, Pb, s) - FF(P, qb, q, s) + FF(qb, Pb, g, s) -
             FF(P, Pb, g, s) - FF(qb, P, g, s) - FF(q, Pb, g, s) +
             h(qb, q, Pb, P) * FF(q, qb, Pb, s) + h(qb, q, g, P) * FF(q, P, g, s) -
             h(qb, Pb, g, P) * FF(Pb, P, g, s));
    // Eq. (32)
    HQQ_QQb(2) =
        xn * (FF(qb, g, q, s) + FF(P, q, g, s) - FF(Pb, g, qb, s) - FF(P, g, q, s) -
              FF(P, q, qb, s) - FF(g, q, qb, s) + FF(g, qb, Pb, s) - FF(q, qb, Pb, s) -
              h(qb, g, q, Pb) * FF(g, qb, q, s)) -
        one / xn *
            (FF(qb, q, P, s) - FF(qb, q, Pb, s) + FF(Pb, qb, q, s) + FF(qb, Pb, g, s) +
             FF(q, P, g, s) - FF(qb, P, g, s) - FF(Pb, P, g, s) -
             h(qb, q, P, Pb) * FF(P, qb, q, s) - h(qb, q, g, Pb) * FF(q, Pb, g, s) -
             h(qb, P, g, Pb) * FF(P, Pb, g, s));

    // Eq. (33)
    for (hQQ = 1; hQQ <= 2; ++hQQ) {
      RR = pntr_RR(hQQ);
      HQQ_qb(hQQ) =
          xn * (FF(qb, g, Pb, s) - FF(qb, g, q, s) + FF(P, q, qb, s) - FF(P, q, g, s) -
                FF(P, Pb, qb, s) - h(qb, g, Pb, RR) * FF(g, qb, Pb, s) +
                h(qb, g, q, RR) * FF(g, qb, q, s) + h(qb, g, P, RR) * FF(g, Pb, P, s));
      Hq_QQb(hQQ) =
          xn * (FF(q, g, P, s) - FF(q, g, qb, s) - FF(P, q, g, s) + FF(qb, q, g, s) +
                h(qb, q, Pb, RR) * FF(q, qb, Pb, s) - h(qb, g, Pb, RR) * FF(g, qb, Pb, s) +
                h(qb, g, Pb, RR) * FF(g, P, Pb, s) - h(qb, q, Pb, RR) * FF(q, P, Pb, s) +
                h(qb, g, q, RR) * FF(g, qb, q, s) - h(qb, q, g, RR) * FF(q, qb, g, s));
    }

    // explicit expressions for tree-level(+,hQQ), so that
    // interchange of labels for hq=1 are properly applied
    aQQ_QQb0_plus(1) = std::pow(za(qb, P), 2) / (za(q, qb) * za(P, Pb)) * za(P, Pb) /
                       (za(P, g) * za(g, Pb));
    aQQ_qb0_plus(1) = std::pow(za(qb, P), 2) / (za(q, qb) * za(P, Pb)) * za(P, qb) /
                      (za(P, g) * za(g, qb));
    aq_QQb0_plus(1) = std::pow(za(P, qb), 2) / (za(P, Pb) * za(q, qb)) * za(q, Pb) /
                      (za(q, g) * za(g, Pb));

    aQQ_QQb0_plus(2) = -std::pow(za(qb, Pb), 2) / (za(q, qb) * za(P, Pb)) * za(P, Pb) /
                       (za(P, g) * za(g, Pb));
    aQQ_qb0_plus(2) = -std::pow(za(qb, Pb), 2) / (za(q, qb) * za(P, Pb)) * za(P, qb) /
                      (za(P, g) * za(g, qb));
    aq_QQb0_plus(2) = -std::pow(za(Pb, qb), 2) / (za(P, Pb) * za(q, qb)) * za(q, Pb) /
                      (za(q, g) * za(g, Pb));

    // assembly per Eq. (30)
    for (hQQ = 1; hQQ <= 2; ++hQQ) {
      if (hq == 2) {
        EQQ_QQb(hq, hQQ) = aQQ_QQb0_plus(hQQ) * HQQ_QQb(hQQ) +           // @coverage-probe
                           aQQ_qb0_plus(hQQ) * HQQ_qb(hQQ) +
                           aq_QQb0_plus(hQQ) * Hq_QQb(hQQ);
      } else {
        EQQ_QQb(hq, 3 - hQQ) = -(aQQ_QQb0_plus(hQQ) * HQQ_QQb(hQQ) +    // @coverage-probe
                                 aQQ_qb0_plus(hQQ) * HQQ_qb(hQQ) +
                                 aq_QQb0_plus(hQQ) * Hq_QQb(hQQ));
      }
    }
  }

  return;
}

extern "C" {
void fillEij_wrapper(std::complex<double>* fza, std::complex<double>* fzb, double* fs,
                      std::complex<double>* faQQ_qb0, std::complex<double>* faQQ_QQb0,
                      std::complex<double>* faq_qb0, std::complex<double>* faq_QQb0,
                      std::complex<double>* fEQQ_qb, std::complex<double>* fEQQ_QQb) {
  using namespace mxpart_mod;

  FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
  FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
  FArray2D<double> s(fs, mxpart, mxpart);
  FArray2D<std::complex<double>> aQQ_qb0(faQQ_qb0, 2, 2);
  FArray2D<std::complex<double>> aQQ_QQb0(faQQ_QQb0, 2, 2);
  FArray2D<std::complex<double>> aq_qb0(faq_qb0, 2, 2);
  FArray2D<std::complex<double>> aq_QQb0(faq_QQb0, 2, 2);
  FArray2D<std::complex<double>> EQQ_qb(fEQQ_qb, 2, 2);
  FArray2D<std::complex<double>> EQQ_QQb(fEQQ_QQb, 2, 2);

  fillEij(za, zb, s, aQQ_qb0, aQQ_QQb0, aq_qb0, aq_QQb0, EQQ_qb, EQQ_QQb);
}
}

// Eq. (24)
static std::complex<double> FF(int i, int j, int k, FArray2D<double>& s) {
  using namespace constants_mod;
  using namespace mxpart_mod;

  int m, n;
  FArray1D<int> check(5);

  // identify complementary labels (m,n) according to Eq. (25)
  check.fill(0);
  check(i) = 1;
  check(j) = 1;
  check(k) = 1;

  for (int r = 1; r <= 4; ++r) {
    if (check(r) == 0) {
      m = r;
      break;
    }
  }
  n = 15 - i - j - k - m;

  return -ddilog(one - s(m, n) / s(i, j)) - ddilog(one - s(m, n) / s(j, k)) -
         half * std::pow(lnrat(-s(i, j), -s(j, k)), 2) - pisqo6;
}

// Kronecker delta(i,j)
static int krondel(int i, int j) {
  if (i == j) {
    return 1;
  } else {
    return 0;
  }
}

