33	  int pntr_r_data[2], pntr_RR_data[2];
34	  FArray1D<int> pntr_r(pntr_r_data, 2);
35	  FArray1D<int> pntr_RR(pntr_RR_data, 2);
36	
37	  int hq, hQQ, r, RR;
38	
39	  FArray1D<std::complex<double>> HQQ_QQb(2), HQQ_qb(2), Hq_QQb(2);
40	  FArray1D<std::complex<double>> aQQ_QQb0_plus(2), aQQ_qb0_plus(2), aq_QQb0_plus(2);
41	
42	  // statement functions
43	  // Eq. (26)
44	  auto h = [&](int i, int j, int k, int l) -> std::complex<double> {
45	    return std::pow(za(i, k) * za(j, l) / (za(i, l) * za(j, k)), 2);
46	  };
