52	  auto GGg4 = [&](int r, int a, int AA, int gg, int RR) -> std::complex<double> {
53	    return std::pow(h(r, a, gg, RR), krondel(RR, AA)) * FF(a, AA, gg, s);
54	  };
55	  auto GGg2 = [&](int r, int gg, int a, int AA, int RR) -> std::complex<double> {
56	    return std::pow(h(r, gg, AA, RR), krondel(r, a)) * FF(gg, a, AA, s);
57	  };
