59	  // pointers, noting that the notation of the paper is translated as follows:
60	  //  q -> q, Q -> QQ, qbar -> qb, Qbar -> QQb
61	  q = 1;
62	  QQ = 2;
63	  qb = 3;
64	  QQb = 4;
65	  g = 5;
66	  P = QQ;
67	  Pb = QQb;
68	  pntr_r_data[0] = q;
69	  pntr_r_data[1] = qb;
70	  pntr_RR_data[0] = QQ;
71	  pntr_RR_data[1] = QQb;
