73	  for (hq = 1; hq <= 2; ++hq) {
74	    r = pntr_r(hq);
75	    for (hQQ = 1; hQQ <= 2; ++hQQ) {
76	      RR = pntr_RR(hQQ);
77	
78	      // Eq. (29)
79	      EQQ_qb(hq, hQQ) =                                                          // @coverage-probe
80	          -aQQ_qb0(hq, hQQ) *
81	              (xn * (FF(qb, g, P, s) + h(r, qb, Pb, RR) * FF(qb, q, Pb, s) +
82	                     h(r, q, g, RR) * FF(q, qb, g, s) + h(r, g, Pb, RR) * FF(g, P, Pb, s) +
83	                     h(r, q, P, RR) * FF(q, Pb, P, s)) -
84	               one / xn *
85	                   (-h(r, q, Pb, RR) * (FF(q, P, Pb, s) + FF(q, qb, Pb, s)) + FF(q, g, Pb, s) -
86	                    h(r, qb, P, RR) * (FF(qb, Pb, P, s) + FF(qb, q, P, s)) + FF(qb, g, P, s) +
87	                    h(r, qb, Pb, RR) * (FF(qb, P, Pb, s) + FF(qb, q, Pb, s)) - FF(qb, g, Pb, s) +
88	                    h(r, q, P, RR) * (FF(q, qb, P, s) + FF(q, Pb, P, s)) - FF(q, g, P, s))) +
89	          aQQ_QQb0(hq, hQQ) *
90	              (xn * h(r, g, Pb, RR) * FF(g, P, Pb, s) -
91	               one / xn *
92	                   (-FF(qb, g, Pb, s) + h(r, qb, g, RR) * FF(qb, q, g, s) + FF(Pb, g, q, s) -
93	                    h(r, q, g, RR) * FF(q, qb, g, s) - htil(r, Pb, g, RR) * FF(Pb, P, g, s) -
94	                    h(r, q, Pb, RR) * (FF(q, P, Pb, s) - FF(q, qb, Pb, s)) +
95	                    h(r, qb, Pb, RR) * (FF(qb, P, Pb, s) - FF(qb, q, Pb, s)) +
96	                    GGg4(r, qb, Pb, g, RR) - GGg4(r, qb, P, g, RR) + GGg4(r, q, P, g, RR) -
97	                    GGg4(r, q, Pb, g, RR))) +
98	          aq_qb0(hq, hQQ) *
99	              (xn * h(r, q, g, RR) * FF(q, qb, g, s) -
100	               one / xn *
101	                   (FF(Pb, g, q, s) - h(r, g, Pb, RR) * FF(g, P, Pb, s) - FF(P, g, q, s) +
102	                    h(r, g, P, RR) * FF(g, Pb, P, s) - htil(r, g, q, RR) * FF(g, qb, q, s) -
103	                    h(r, q, Pb, RR) * (FF(q, qb, Pb, s) - FF(q, P, Pb, s)) +
104	                    h(r, q, P, RR) * (FF(q, qb, P, s) - FF(q, Pb, P, s)) +
105	                    GGg2(r, g, qb, Pb, RR) - GGg2(r, g, q, Pb, RR) + GGg2(r, g, q, P, RR) -
106	                    GGg2(r, g, qb, P, RR)));
