110	  for (hq = 1; hq <= 2; ++hq) {
111	    // pointers, noting that the notation of the paper is translated as follows:
112	    //  q -> q, Q -> QQ, qbar -> qb, Qbar -> QQb
113	    // and that the hq=1 corresponds to qb<->q, Qbar<->Q, c.f. Eqs. (14) and (15)
114	    if (hq == 2) {
115	      q = 1;
116	      QQ = 2;
117	      qb = 3;
118	      QQb = 4;
119	      g = 5;
120	    } else {
121	      q = 3;
122	      QQ = 4;
123	      qb = 1;
124	      QQb = 2;
125	      g = 5;
126	    }
