134	    // Eq. (31)
135	    HQQ_QQb(1) =
136	        xn * (FF(qb, g, q, s) + FF(P, q, g, s) - FF(Pb, g, qb, s) - FF(P, g, q, s) -
137	              FF(P, q, qb, s) - FF(g, q, qb, s) + h(qb, g, Pb, P) * FF(g, qb, Pb, s) -
138	              h(qb, q, Pb, P) * FF(q, qb, Pb, s) - h(qb, g, q, P) * FF(g, qb, q, s)) -
139	        one / xn *
140	            (FF(qb, q, P, s) - FF(qb, q, Pb, s) - FF(P, qb, q, s) + FF(qb, Pb, g, s) -
141	             FF(P, Pb, g, s) - FF(qb, P, g, s) - FF(q, Pb, g, s) +
142	             h(qb, q, Pb, P) * FF(q, qb, Pb, s) + h(qb, q, g, P) * FF(q, P, g, s) -
143	             h(qb, Pb, g, P) * FF(Pb, P, g, s));
