145	    HQQ_QQb(2) =
146	        xn * (FF(qb, g, q, s) + FF(P, q, g, s) - FF(Pb, g, qb, s) - FF(P, g, q, s) -
147	              FF(P, q, qb, s) - FF(g, q, qb, s) + FF(g, qb, Pb, s) - FF(q, qb, Pb, s) -
148	              h(qb, g, q, Pb) * FF(g, qb, q, s)) -
149	        one / xn *
150	            (FF(qb, q, P, s) - FF(qb, q, Pb, s) + FF(Pb, qb, q, s) + FF(qb, Pb, g, s) +
151	             FF(q, P, g, s) - FF(qb, P, g, s) - FF(Pb, P, g, s) -
152	             h(qb, q, P, Pb) * FF(P, qb, q, s) - h(qb, q, g, Pb) * FF(q, Pb, g, s) -
153	             h(qb, P, g, Pb) * FF(P, Pb, g, s));
154	
155	    // Eq. (33)
156	    for (hQQ = 1; hQQ <= 2; ++hQQ) {
157	      RR = pntr_RR(hQQ);
158	      HQQ_qb(hQQ) =
159	          xn * (FF(qb, g, Pb, s) - FF(qb, g, q, s) + FF(P, q, qb, s) - FF(P, q, g, s) -
160	                FF(P, Pb, qb, s) - h(qb, g, Pb, RR) * FF(g, qb, Pb, s) +
161	                h(qb, g, q, RR) * FF(g, qb, q, s) + h(qb, g, P, RR) * FF(g, Pb, P, s));
162	      Hq_QQb(hQQ) =
163	          xn * (FF(q, g, P, s) - FF(q, g, qb, s) - FF(P, q, g, s) + FF(qb, q, g, s) +
164	                h(qb, q, Pb, RR) * FF(q, qb, Pb, s) - h(qb, g, Pb, RR) * FF(g, qb, Pb, s) +
165	                h(qb, g, Pb, RR) * FF(g, P, Pb, s) - h(qb, q, Pb, RR) * FF(q, P, Pb, s) +
