223	// Eq. (24)
224	static std::complex<double> FF(int i, int j, int k, FArray2D<double>& s) {
225	  using namespace constants_mod;
226	  using namespace mxpart_mod;
227	
228	  int m, n;
229	  FArray1D<int> check(5);
230	
231	  // identify complementary labels (m,n) according to Eq. (25)
232	  check.fill(0);
233	  check(i) = 1;
234	  check(j) = 1;
235	  check(k) = 1;
236	
237	  for (int r = 1; r <= 4; ++r) {
238	    if (check(r) == 0) {
239	      m = r;
240	      break;
241	    }
242	  }
243	  n = 15 - i - j - k - m;
244	
245	  return -ddilog(one - s(m, n) / s(i, j)) - ddilog(one - s(m, n) / s(j, k)) -
246	         half * std::pow(lnrat(-s(i, j), -s(j, k)), 2) - pisqo6;
247	}
